// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY, LogFile} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;
    // a contract counterpart with code but no AddMessage: the mutant wrongly
    // binds the logger to this address and then Put's log call reverts
    address actor;

    function setUp() public {
        c = new PENNY_BY_PENNY();
        actor = address(new Actor());
    }

    function testFuzz_property(address holder, uint256 lockTime, uint256 amount) public {
        vm.assume(holder != address(0) && holder != actor && holder != address(c));
        lockTime = bound(lockTime, 0, 10 ** 18);
        amount = bound(amount, 0, 10 ** 30);

        // any caller may initialize the log target
        vm.prank(actor);
        c.SetLogFile(address(new LogFile()));

        // seed a balance for the holder (also exercises Put on the real log)
        vm.deal(holder, amount);
        vm.prank(holder);
        c.Put{value: amount}(lockTime);

        // afterwards, any holder's Put must still succeed because messages
        // are logged to the genuine LogFile set by SetLogFile
        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.Put{value: amount}(lockTime) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract Actor {
    // has code but exposes no AddMessage/fallback: receiving a log call reverts
}
